#include <bits/stdc++.h>
using namespace std;

// Codeforces 161D - Distance in Tree
// Topic: 463. DP on Trees and DAGs

int n;
vector<vector<int>> adj;
vector<long long> val;
vector<array<long long, 2>> dp;

void dfs(int u, int p) {
    dp[u][0] = 0;
    dp[u][1] = val[u];

    for (int v : adj[u]) {
        if (v == p) continue;
        dfs(v, u);

        dp[u][0] += max(dp[v][0], dp[v][1]);
        dp[u][1] += dp[v][0];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    val.resize(n + 1);
    for (int i = 1; i <= n; ++i) cin >> val[i];

    adj.assign(n + 1, vector<int>());
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    dp.assign(n + 1, {0, 0});
    dfs(1, 0);

    cout << max(dp[1][0], dp[1][1]) << "\n";
    return 0;
}
